  if (hasProtocol(pathname)) {
    return undefined;
  }

  const normalizedPathname = addLeadingSlash(removeTrailingSlash(pathname));

  // We sort by descending path length so that the most specific version path
  // is matched first. This is especially important when a version is mounted at
  // the root path ("/"): it should only be selected when no other version path
  // matches, otherwise it would always be considered active.
  const orderedVersions = [...data.versions].sort(
    (a, b) =>
      addLeadingSlash(removeTrailingSlash(b.path)).length -
      addLeadingSlash(removeTrailingSlash(a.path)).length,
  );

  return orderedVersions.find((version) => {
    const normalizedVersionPath = addLeadingSlash(
      removeTrailingSlash(version.path),
    );

    // The root version path matches all paths, but is tested last
    if (normalizedVersionPath === '/') {
      return true;
    }

    return (
      normalizedPathname === normalizedVersionPath ||
      normalizedPathname.startsWith(`${normalizedVersionPath}/`)
    );
  });
}

